input.command:
mkdir -p /tmp/opencode && xvfb-run -a node - <<'NODE'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:false, executablePath:'/usr/bin/chromium', args:['--enable-gpu','--ignore-gpu-blocklist','--enable-unsafe-webgpu','--use-angle=vulkan','--enable-features=Vulkan','--use-vulkan=swiftshader','--disable-vulkan-surface','--no-sandbox']});
 const page=await browser.newPage({viewport:{width:1152,height:768},deviceScaleFactor:1});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://localhost:3002');await page.waitForTimeout(600);
 await page.locator('#startBtn').click();await page.waitForTimeout(2200);
 const score=await page.locator('#score').textContent();
 await page.screenshot({path:'/tmp/opencode/star-runner.jpg',type:'jpeg',quality:78});
 await page.keyboard.press('p');await page.waitForTimeout(100);
 const paused=await page.locator('#pauseOverlay').evaluate(el=>!el.classList.contains('hidden'));
 console.log(JSON.stringify({title:await page.title(),score,paused,errors},null,2));
 await browser.close();
})();
NODE

